export const selfLayers=[{"id":"body-self","name":"身体载具我","place":"身体与生命体验","function":"承载生命，参与感受与行动。","intro":"身体有自己的构成、运行节律与感知方式。认识身体，是理解自己的承载条件，留意身体状态，并把真实需要带入生活安排。","deep":"身体有自己的构成、运行节律与感知方式。认识身体，是理解自己的承载条件，留意身体状态，并把真实需要带入生活安排。","parts":["body-structure","life-regulation","body-sensation"],"aspects":[["物质结构","从器官、组织与细胞等角度，认识身体的构成与承载条件。"],["生命调节","理解身体维持与调整自身状态的过程，照顾生活节律。"],["身体感知","留意疲劳、饥饿、紧张与舒展，理解身体正在传递的信息。"]]},{"id":"external-self","name":"外在角色我","place":"名字、故事与身份","function":"承担现实角色，参与生活与创造。","intro":"名字、故事、身份与评价，构成了我们熟悉的“我”。从名相、欲求与惯性三个入口，看见角色怎样运作，学习与它相处。","deep":"名字、故事、身份与评价，构成了我们熟悉的“我”。从名相、欲求与惯性三个入口，看见角色怎样运作，学习与它相处。","parts":[],"aspects":[["名相","我以为我是谁：名字、故事、名分、名声与功名。"],["欲求","我要什么，怕什么：安全、认可、归属与掌控。"],["惯性","我习惯怎样做：讲故事、照旧做、比较、预演与防御。"]]},{"id":"inner-consciousness","name":"内在意识我","place":"相识、对话与融合","function":"让内在的王归位，活出生命的最高版本。","intro":"相识，认识模拟背后的自己；对话，听懂内在的表达；融合，让生命由更深处的自己引领。","deep":"从相识、对话到融合，重新认识自己，并让这份联系进入实际生活。","parts":[],"aspects":[["相识","什么是内在意识我？"],["对话","内在意识我如何与我们对话？"],["融合","当摄政王交还王权。"]]}];
