export const selfAliases={"inner-role": "", "heaven-soul": "inner-consciousness", "human-soul": "external-self", "earth-soul": "life-regulation", "thinking-self": "logic", "feeling-self": "emotion", "godhead-a": "inner-consciousness", "godhead-b": "inner-consciousness", "godhead-c": "inner-consciousness"};

const crumbs=(tail='')=>`<nav class="breadcrumbs" aria-label="当前位置"><a href="#/">首页</a><span>/</span><a href="#/ren">人道</a><span>/</span>${tail?'<a href="#/knowing">认识自己</a><span>/</span><span aria-current="page">'+tail+'</span>':'<span aria-current="page">认识自己</span>'}</nav>`;
const cards=items=>`<div class="kn-three">${items.map(([t,p])=>`<div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>`;
const related=l=>l.id==='inner-consciousness'?'<div class="kn-related"><a href="#/knowing/inner-consciousness/recognition">相识 ↗</a><a href="#/knowing/inner-consciousness/dialogue">对话 ↗</a><a href="#/knowing/inner-consciousness/integration">融合 ↗</a></div>':`<div class="kn-related">${l.parts.map(id=>`<a href="#/knowing/${id}">${selfElements.find(e=>e.id===id).name} ↗</a>`).join('')}</div>`;
const compactStructure=(active='')=>`<section class="kn-compact" aria-label="三个我的完整结构"><p class="kn-compact-formula">身体载具我 · 外在角色我 · 内在意识我</p><div class="kn-compact-table">${selfLayers.map(l=>`<div class="kn-compact-row${l.id===active?' is-current':''}"><a class="kn-compact-label" href="#/knowing/${l.id}" ${l.id===active?'aria-current="page"':''}>${l.name}</a><div class="kn-compact-parts">${l.parts.length?l.parts.map(id=>`<a href="#/knowing/${id}">${selfElements.find(e=>e.id===id).name}</a>`).join(''):l.aspects.map(([name])=>`<span class="kn-angle">${name}</span>`).join('')}</div></div>`).join('')}</div><p class="kn-core-note">身体从三个面向展开，角色从名相、欲求与惯性三个入口理解；内在意识从相识、对话到融合，逐步建立更完整的联系。</p></section>`;
const sourceNote=()=>`<details class="kn-sources"><summary>思想来源与术语</summary><div><p>三个“我”是《三道哲学》对自我认识的组织方式，受到细雨资料与赛斯体系的启发。它们描述同一生命相互联系的层面。</p><p>名相、欲求与惯性，是“外在角色我”一章整理的三个观察入口；相识、对话与融合，是与内在意识我逐步建立联系的阅读路径。</p></div></details>`;
const structure=(l,i)=>`<details class="kn-layer-fold"><summary><span class="eyebrow">0${i+1} / ${l.parts.length?'理解这一层':'三个理解角度'}</span><span><strong>${l.name}</strong><small>${l.function}</small></span><b aria-hidden="true">＋</b></summary><div class="kn-layer-content"><p class="kn-body">${l.intro}</p>${cards(l.aspects)}${related(l)}<a class="text-link" href="#/knowing/${l.id}">深入理解${l.name} ↗</a></div></details>`;
export function knowingPage(){return `<div class="page-shell knowing-page kn-framework">${crumbs()}<header class="kn-head"><p class="eyebrow">人道 / 认识自己</p><h1>认识自己</h1><p class="kn-intro">身体载具我承载生命与体验，外在角色我参与现实生活，内在意识我展开觉察与创造。三个层面相互联系，帮助我们认识完整的自己。</p></header>${compactStructure()}${selfLayers.map(structure).join('')}<section class="kn-section"><span class="eyebrow">04 / 三层如何协同</span><h2>在具体生活中，认识完整的自己。</h2><div class="kn-flow">${selfLayers.map(l=>`<div><h3>${l.name}</h3><p>${l.function}</p></div>`).join('')}<p>真实经历带来新的理解，新的理解继续参与选择与行动。</p></div><div class="kn-example"><h3>面对一次重要的事业选择</h3><p><strong>身体载具我：</strong>留意疲惫、紧张与精力，理解自己当前的承载条件。</p><p><strong>外在角色我：</strong>辨认自己执着的身份、想要与害怕的事，以及习惯的反应，再作出能够承担的选择。</p><p><strong>内在意识我：</strong>觉察自己是否被熟悉的身份与评价限制，探索真正珍视的方向与新的可能。</p></div><div class="kn-related"><a href="#/awareness">通过觉察认识自己 ↗</a><a href="#/acceptance">继续理解接纳自己 ↗</a><a href="#/becoming">通过选择创造自己 ↗</a></div></section>${sourceNote()}<a class="kn-next" href="#/ren">返回人道 <span>→</span></a></div>`;}
export function selfLayerPage(id){if(id==='body-self')return bodySelfPage();if(id==='external-self')return externalRolePage();const l=selfLayers.find(x=>x.id===id);if(!l)return '';if(id==='inner-consciousness')return innerPage();if(personalityContent[id])return personalityPage(id,selfLayers,selfElements,compactStructure);return `<div class="page-shell knowing-page kn-reading">${crumbs(l.name)}<header class="kn-head"><p class="eyebrow">认识自己 / ${l.place}</p><h1>${l.name}</h1><p class="kn-intro">${l.intro}</p></header>${compactStructure(id)}<section class="kn-section"><h2>${l.function}</h2>${cards(l.aspects)}${related(l)}</section>${sourceNote()}<a class="kn-next" href="#/knowing">返回认识自己 <span>→</span></a></div>`;}
export function selfElementPage(id){const e=selfElements.find(x=>x.id===id);if(!e)return '';if(personalityContent[id])return personalityPage(id,selfLayers,selfElements,compactStructure);const l=selfLayers.find(x=>x.id===e.layer);return `<div class="page-shell knowing-page kn-reading">${crumbs(e.name)}<header class="kn-head"><p class="eyebrow">${l.name}</p><h1>${e.name}</h1><p class="kn-essence">${e.essence}</p><p class="kn-intro">${e.intro}</p></header><section class="kn-section"><h2>带回生活</h2><p class="kn-body">${e.example}</p><ol class="kn-questions">${e.questions.map(q=>`<li>${q}</li>`).join('')}</ol></section>${related(l)}${sourceNote()}<a class="kn-next" href="#/knowing/${l.id}">返回${l.name} <span>→</span></a></div>`;}
export function initKnowing(){document.querySelectorAll('.kn-layer-fold').forEach(d=>d.addEventListener('toggle',()=>{d.querySelector('summary>b').textContent=d.open?'−':'＋';}));}
